import torch
import torch.nn as nn
import triton
import triton.language as tl


@triton.autotune(
    configs=[
        triton.Config({"BLOCK_SIZE": 1024}, num_warps=4, num_stages=2),
        triton.Config({"BLOCK_SIZE": 2048}, num_warps=8, num_stages=2),
        triton.Config({"BLOCK_SIZE": 4096}, num_warps=8, num_stages=2),
        triton.Config({"BLOCK_SIZE": 4096}, num_warps=16, num_stages=2),
        triton.Config({"BLOCK_SIZE": 8192}, num_warps=16, num_stages=2),
    ],
    key=["N"],
)
@triton.jit
def l2_norm_kernel(
    x_ptr,
    out_ptr,
    M,
    N,
    stride_m,
    stride_n,
    BLOCK_SIZE: tl.constexpr,
):
    row = tl.program_id(0)
    row_start = row * stride_m

    sum_sq = tl.zeros((BLOCK_SIZE,), dtype=tl.float32)
    for off in range(0, N, BLOCK_SIZE):
        cols = off + tl.arange(0, BLOCK_SIZE)
        mask = cols < N
        x = tl.load(x_ptr + row_start + cols * stride_n, mask=mask, other=0.0).to(
            tl.float32
        )
        sum_sq += x * x

    norm_sq = tl.sum(sum_sq, axis=0)
    inv_norm = 1.0 / tl.sqrt(norm_sq + 1e-12)

    for off in range(0, N, BLOCK_SIZE):
        cols = off + tl.arange(0, BLOCK_SIZE)
        mask = cols < N
        x = tl.load(x_ptr + row_start + cols * stride_n, mask=mask, other=0.0).to(
            tl.float32
        )
        out = x * inv_norm
        tl.store(out_ptr + row_start + cols * stride_n, out.to(tl.bfloat16), mask=mask)


class Model(nn.Module):
    def __init__(self):
        super(Model, self).__init__()

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        x = x.contiguous()
        M, N = x.shape
        out = torch.empty_like(x)
        grid = (M,)
        l2_norm_kernel[grid](
            x,
            out,
            M,
            N,
            x.stride(0),
            x.stride(1),
        )
        return out
